 }

+// progressProblem returns problem whole when it has at most n runes. A longer problem that
+// starts with a quoted requirement (requirement "<statement>" <reason>) has the statement
+// shortened with cutAtWord and the reason kept whole, so the line may pass n runes when the
+// reason leaves no room. Any other longer problem is cut at n runes.
+func progressProblem(problem string, n int) string {
+	const open = `requirement "`
+	if utf8.RuneCountInString(problem) <= n || !strings.HasPrefix(problem, open) {
+		return cutAtWord(problem, n)
+	}
+	rest := problem[len(open):]
+	i := strings.Index(rest, `" `)
+	if i < 0 {
+		return cutAtWord(problem, n)
+	}
+	statement, tail := rest[:i], rest[i:]
+	room := n - utf8.RuneCountInString(open) - utf8.RuneCountInString(tail)
+	if room < 0 {
+		room = 0
+	}
+	return open + cutAtWord(statement, room) + tail
+}
+
