package review

import (
	"fmt"
	"strings"
	"testing"
	"unicode/utf8"
)

type progressEnv struct {
	Env
	lines []string
}

func (e *progressEnv) Progress(line string) { e.lines = append(e.lines, line) }
func (e *progressEnv) Event(map[string]any) {}

func rejectedProgress(t *testing.T, problem string) string {
	t.Helper()
	e := &progressEnv{}
	r := &run{in: Input{Number: 1}, env: e}
	r.allowance("rejected_verdict", []string{problem})
	if len(e.lines) != 1 {
		t.Fatalf("progress lines: %q", e.lines)
	}
	prefix := "kogen: review 1: verdict not accepted: "
	if !strings.HasPrefix(e.lines[0], prefix) {
		t.Fatalf("line %q lacks prefix %q", e.lines[0], prefix)
	}
	return strings.TrimPrefix(e.lines[0], prefix)
}

func TestRejectedLineKeepsReason(t *testing.T) {
	const reason = "has no evidence: probe it with shell against the candidate before the verdict"
	statement := string([]rune(strings.Repeat("abcdefghij ", 40))[:400])

	long := fmt.Sprintf("requirement %q %s", statement, reason)
	got := rejectedProgress(t, long)
	want := `requirement "` + strings.TrimSuffix(strings.Repeat("abcdefghij ", 5), " ") + ` ..." ` + reason
	if got != want {
		t.Errorf("long requirement: got %q want %q", got, want)
	}
	if utf8.RuneCountInString(got) > progressProblemRunes {
		t.Errorf("long requirement: %d runes", utf8.RuneCountInString(got))
	}

	short := fmt.Sprintf("requirement %q %s", "a short requirement", reason)
	if got := rejectedProgress(t, short); got != short {
		t.Errorf("short requirement: got %q want %q", got, short)
	}

	longReason := strings.Repeat("reason ", 40)
	got = rejectedProgress(t, fmt.Sprintf("requirement %q %s", statement, longReason))
	if want := `requirement " ..." ` + longReason; got != want {
		t.Errorf("long reason: got %q want %q", got, want)
	}

	plain := string([]rune(strings.Repeat("abcdefghij ", 20))[:200])
	if got, want := rejectedProgress(t, plain), strings.TrimSuffix(strings.Repeat("abcdefghij ", 14), " ")+" ..."; got != want {
		t.Errorf("no requirement: got %q want %q", got, want)
	}
}

